INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ADONIS_HERO_APOLLO','ENT_ADONIS_HERO','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Compare Adonis, Attis, Osiris, 3rd ed. i. 174 sgqg. The Hercules whom Greek tradition associated with Omphale was probably an Oriental deity identical with the Sandan of Tarsus. See Adonis, Attis, Osiris, i. 124 sqq. 275 T 2.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_AEACUS_HERO_APOLLO','ENT_AEACUS_HERO','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Aeacus, son of Aegina, his righteousness, his prayer for rain; father of Peleus and Telamon, who are banished for the murder of their brother Phocus. Telamon becomes king of Salamis; father of Ajax and Teucer, xli. 6=7.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_AEGINA_APOLLO','ENT_AEGINA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','1765-1772, from whose account we gather that this story was told to explain the origin of a foot-race in Aegina, in which young men ran with jars full of water on their shoulders. 11g APOLLODORUS ἦλθον, Tov πάντα πλοῦν ἐν τέτταρσι μησὶ τελειώ- σαντες.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_AEGLE_HESPERID_APOLLO','ENT_AEGLE_HESPERID','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.5.11','With it the Hesperides also were on guard, to wit, Aegle, Ery- thia, Hesperia, and Arethusa. So journeying he came to the river Echedorus. And Cycnus, son of Ares and Pyrene, challenged him to single combat. Ares championed the cause of Cycnus and marshalled the combat, but a thunderbolt was hurled between the two and parted the combatants. And going on of the gods beside Mount Atlas.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_AENEAS_GREEK_RECEPTION_APOLLO','ENT_AENEAS_GREEK_RECEPTION','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','2 On the reception of Hercules by Ceyx, see Diodorus Siculus, iv. 36. 5; Pausanias, i. 32.6, As to the conquest of the Dryopians by Hercules, see Herodotus, viii. 43, compare 73; Diodorus Siculus, iv. 37. 1 δᾳ.; Strabo, viii. 6. 13, p. 373; Pausanias, iv. 34. 9 sq.; Nonnus, in Westermann''s Mytho: graphi Graeci, Appendix Narrationum, xxix. 6, p. 371; Scholiast on Apollonius Rhodius, Argon. i.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ARETHUSA_HESPERID_APOLLO','ENT_ARETHUSA_HESPERID','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.5.11','With it the Hesperides also were on guard, to wit, Aegle, Ery- thia, Hesperia, and Arethusa. So journeying he came to the river Echedorus. And Cycnus, son of Ares and Pyrene, challenged him to single combat. Ares championed the cause of Cycnus and marshalled the combat, but a thunderbolt was hurled between the two and parted the combatants. And going on of the gods beside Mount Atlas.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ARISTAEUS_HERO_APOLLO','ENT_ARISTAEUS_HERO','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','4 Autonoe and Aristaeus had a son Actaeon, who was bred by Chiron to be a hunter and then afterwards was devoured on Cithaeron by his own dogs.1 He perished in that way, according to Acusilaus, because Zeus was angry at him for wooing Semele; but according to the more general opinion, it was because he saw Artemis bathing.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ASCALAPHUS_APOLLO','ENT_ASCALAPHUS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 1.5.3:','Persephone remains with Pluto (Ascalaphus), v. Battle of the gods and giants, vi. 1-2. Typhon, vi. ὃ. 1 Translated, with some modifications, from the Arygu- mentum prefixed to R. Wagner''s edition of Apollodorus. xlv SUMMARY I].-Tue Famity or DEvcALion. Book I., Chaps. v11.-1x. Prometheus creates men, and for the theft of fire is nailed to the Caucasus, vii. 1. Deucalion and.Pyrrha saved from the flood, vii. 1-2.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ATALANTA_APOLLO','ENT_ATALANTA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 3.9.2','And when they were assembled, Oeneus entertained them for nine days; but on the tenth, when Cepheus and An- caeus and some others disdained to go a-hunting with a woman, Meleager compelled them to follow the chase with her, for he desired to have a child also by Atalanta, though he had to wife Cleopatra, daughter of Idas and Marpessa.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CASSANDRA_APOLLO','ENT_CASSANDRA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 3.12.5:','1036 sg.; und Appendix, ‘‘''The Resurrec- tion of Glaucus." ᾿ 5 Τὸ is said that when Cassandra refused to grant her favours to Apollo in return for the gift of prophecy which he had bestowed on her, he spat into her mouth and so prevented her from convincing anybody of the truth of her prophecies. See Servius, on Virgil, Aen. ii. 247. On ancient superstitions about spittle, see Pliny, Nat. Hist. xxviii. 35 sqq.; C.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHARON_APOLLO','ENT_CHARON','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Apparently they thought that it would be a waste of money to pay Charon for ferrying them across to hell when they could get there for nothing from their own backdoor. 1 Compare Homeric Hymn to Demeter, 98 sqq., who says that Demeter, sad at heart, sat down by the wayside at the Maiden''s Well, under the shadow of an olive-tree. Later in the poem (vv.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHIMERA_APOLLO','ENT_CHIMERA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.3.1','Having read the letter, Tobates ordered him to kill the Chimera, believing that he would be destroyed by the beast, for it was more than a match for many, let alone one; it had the fore part of a lion, the tail of a dragon, and its third head, the middle one, was that of a goat, through which it belched fire. And it devastated the country and harried the cattle; for it was a single creature with the power of three beasts.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CYLLENE_APOLLO','ENT_CYLLENE','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 3.8.1:','That the wife of Pelasgus and mother of Lycaon was Cyllene is affirmed by the Scholiast on Euripides, Orestes, 1645. 389 APOLLODORUS ὑπερηφανίᾳ καὶ ἀσεβείᾳ. Ζεὺς δὲ αὐτῶν βουλό- μενος τὴν ἀσέβειαν πειρᾶσαι εἰκασθεὶς ἀνδρὶ χερνήτῃ παραγίνεται. οἱ δὲ αὐτὸν ἐπὶ ξένια καλέσαντες, σφάξαντες ἕνα τῶν ἐπιχωρίων παῖδα, τοῖς ἱεροῖς τὰ τούτου σπλάγχνα συναναμίξαντες παρέθεσαν, συμβουλεύσαντος τοῦ πρεσβυτέρου ἀδελφοῦ Μαινάλου.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CYRENE_APOLLO','ENT_CYRENE','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','The eighth labour he enjoined on him was to bring the mares of Diomedes the Thracian to Mycenae.! Now this Diomedes was a son of Ares and Cyrene, and he was king of the Bistones, a very war-like Thracian people, and he owned man-eating mares. So Hercules sailed with a band of volunteers, and having overpowered the grooms who were in charge of the mangers, he drove the mares to the sea.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ERECHTHEUS_APOLLO','ENT_ERECHTHEUS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Amongst these indications is the author''s acquaintance with the ‘‘ sea of Erechtheus " and the sacred olive-tree on the Acropolis of Athens. See Apollodorus, iii. 14. 1. 2 This is recognized by Professor C. Robert, De Apollodors 54, Bibliotheca, p. xvii VOL. 1. b INTRODUCTION for the sake of literary effect.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ERYTHEIA_HESPERID_APOLLO','ENT_ERYTHEIA_HESPERID','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.5.11','With it the Hesperides also were on guard, to wit, Aegle, Ery- thia, Hesperia, and Arethusa. So journeying he came to the river Echedorus. And Cycnus, son of Ares and Pyrene, challenged him to single combat. Ares championed the cause of Cycnus and marshalled the combat, but a thunderbolt was hurled between the two and parted the combatants. And going on of the gods beside Mount Atlas.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GERYON_APOLLO','ENT_GERYON','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 2.5.10:','to As a tenth labour he was ordered to fetch the kine of Geryon from Erythia.1 Now Erythia was an island near the ocean; it is now called Gadira.? This island was inhabited by Geryon, son of Chrysaor by Callirrhoe, daughter of Ocean.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_GORGYRA_APOLLO','ENT_GORGYRA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 1.5.3:','3 Not foreseeing the consequence, she swallowed it; and because Ascalaphus, son of Acheron and Gorgyra, bore witness against her, Demeter laid a heavy rock on him in Hades.!_ But Persephone was compelled to remain a third of every year with Pluto and the rest of the time with the gods.? gave him a basket of cooked food, saying, ‘‘ When you reach the lower regions, eat sparingly of your provisions that they may last, and you ma','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HESPERIA_HESPERID_APOLLO','ENT_HESPERIA_HESPERID','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.5.11','With it the Hesperides also were on guard, to wit, Aegle, Ery- thia, Hesperia, and Arethusa. So journeying he came to the river Echedorus. And Cycnus, son of Ares and Pyrene, challenged him to single combat. Ares championed the cause of Cycnus and marshalled the combat, but a thunderbolt was hurled between the two and parted the combatants. And going on of the gods beside Mount Atlas.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_JASON_APOLLO','ENT_JASON','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.9.16-27','Jason, with the help of Medea, tames the bulls, xlvi SUMMARY conquers the earth-born men, and carries off the Golden Fleece. The Argonauts set out with Medea (the murder of Apsyrtus), ix. 23-24. As they sail past the Eridanus, Zeus causes them to wander; they are purified for the murder of Apsyrtus by Circe, ix. 24, sailing past the Sirens, Scylla, and Charybdis, they come to the Phaea- cians, ix.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MARSYAS_APOLLO','ENT_MARSYAS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.4.2','That the tree on which Marsyas was hanged was a pine is affirmed by many ancient writers besides Apollodorus. See Nicander, Aleat- pharmaca, 301 8ᾳ., with the Scholiast''s note; Lucian, Trago- 39 THE LIBRARY, I. rv. 2-3 engaged in a musical contest with Apollo.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MEDEA_APOLLO','ENT_MEDEA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.9.24-28','But Mermerus and Pheres, the children whom Medea had by Jason, she killed, and having got from the Sun a car drawn by winged dragons she fled on it to Athens.? Another tradition is that on her flight she left behind her children, who were still infants, setting them as suppliants on the altar of Hera of the served up at a banquet of the aes by his cruel father Tanta- lus, the deities in pity restored him to life by boiling him','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MEDUSA_APOLLO','ENT_MEDUSA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.4.2-3','When her head was cut off, there sprang from the Gorgon the winged horse Pegasus and Chrysaor, the father of Geryon; these she had by Poseidon.* So Perseus put the head of Medusa in the wallet (Atbisis) and went back again; but the Gorgons started up from their slum- ber and pursued Perseus: but they could not see him on account of the cap, for he was hidden by it.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MELAMPUS_APOLLO','ENT_MELAMPUS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 1.9.11:','2 As to the mode in which Melampus learned the language of birds, and with it the art of divination, from serpents in return for the kindness which he had shown to their species, see Scholiast on Apollonius Rhodius, Argon. i. 118; compare Eustathius on Homer, Od. xi. 292, p. 1685; Pliny, Nat. Hist. x. 137. Helenus and Cassandra are said to have acquired their prophetic power in like manner.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MELIA_APOLLO','ENT_MELIA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 2.1.1:','Ocean and Tethys had a son Inachus, after whom a river in Argos is called Inachus.1_ He and Melia, daughter of Ocean, had sons, Phoroneus and Aegia- leus. Aegialeus having died childless, the whole country was called Aegialia; and Phoroneus, reigning over the whole land afterwards named Peloponnese, begat Apis and Niobe by a nymph Teledice.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MEMNON_APOLLO','ENT_MEMNON','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Achilles slays Memnon, but is shot by lv SUMMARY Apollo and Paris, 3. His body and his arms are rescued by Ajax and Ulysses, 4. The burial of Achilles, 5. Competition of Ajax and Ulysses for the arms of Achilles. Death and burial of Ajax, 6-7. In accordance with a prophecy of Calchas, Ulysses and Diomedes fetch Philoctetes, who shvots Paris, 8. Quarrel between Deiphobus and Helenus for the hand of Helen.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MINOS_HERO_APOLLO','ENT_MINOS_HERO','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','431, according to whom the bull was sent, in answer to Minos''s prayer, not by Poseidon but by Jupiter (Zeus). 304 THE LIBRARY, III. 1. 3-4 and in proof of it he said that whatever he prayed for would be done. And in sacrificing to Poseidon he prayed that.a bull might appear from the depths, promising to sacrifice it when it appeared.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MINOTAUR_APOLLO','ENT_MINOTAUR','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Apollodorus 3.1.4:','And she gave birth to Asterius, who was called the Minotaur. He had the face of a bull, but the rest of him was human; and Minos, in compliance with certain oracles, shut him up and guarded him in the Labyrinth. Now the Labyrinth which Daedalus constructed was a chamber " that 2 Compare Herodotus, i. 171; Thucydides, i. 4 and 8.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_MOPSUS_APOLLO','ENT_MOPSUS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Amphilochus, Calchas, Leonteus, Polypoetes, and Poda- lirius go by land to Colophon, where Calchas is vanquished by Mopsus in a contest of skill and is buried by his companions, 2-4. lvi SUMMARY The fleet of Agamemnon is dispersed by a storm oft Tenos. Shipwreck, death, and burial of Ajax, 5-6. Many are shipwrecked and perish through the false lights displayed by Nauplius at Cape Caphereus, 7.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NEMEAN_LION_APOLLO','ENT_NEMEAN_LION','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.5.1','First, Eurys- theus ordered him to bring the skin of the Nemean lion;2 now that was an invulnerable beast begotten by Typhon. On his way to attack the lion he came to Cleonae and lodged at the house of a day-labourer, Molorchus;* and when his host would have offered a victim in sacrifice, Hercules told him to wait for thirty days, and then, if he had returned safe from the hunt, to sacrifice to Saviour Zeus, but if he were dea','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_OENOMAUS_APOLLO','ENT_OENOMAUS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Pelops, with the help of Myrtilus, vanquishes Oenomaus, marries Hippo- damia, kills Myrtilus, and takes possession of Peloponnese, 3-9. Sons of Pelops: Atreus and Thyestes (the golden lamb, Aerope, backward journey of the sun, the cannibal feast, Aegisthus), 10-14. Agamemnon and Menelaus are brought up by Polyphides and Oeceneus, 15 (Tzetzes). Agamemnon marries Clytaemnestra, and Menelaus marries Helen, 16. XII.-ANTEHOMERICA.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_PALAMEDES_APOLLO','ENT_PALAMEDES','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Epitome 3.8:','Ulysses feigns madness (death of Palamedes), Cinyras sends toy ships. The Wine-growers, 6-10. liv SUMMARY Catalogue of the ships, 11-14. The portent at Aulis, 15. Agamemnon and Achilles chosen leaders, 16. The Mysian war. Telephus wounded by Achilles. Return of the Greeks, 17-18. In the tenth year after the rape of Helen the Greeks again assemble. Telephus, being healed by Achilles, shows them the way, 19-20.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_PYLADES_APOLLO','ENT_PYLADES','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Some said te was shot by Apollo at Delphi for not consulting the oracle, but others said he was murdered by the children of Pylades and Electra (Pausanias, iii. 1.6). Apollodorus clearly adopts the former of these two accounts; the rationalistic Pausanias preferred the latter. 3 Compare Herodotus, vi. 52.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_RHADAMANTHYS_HERO_APOLLO','ENT_RHADAMANTHYS_HERO','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Pseudo-Apollodorus, Library','Meantime Hermes had carried off the real Alemena to the Islands of the Blest, where she was married to Rhadamanthys. See Antoninus Liberalis, 7''ransform. 33. This quaint story is alluded to by Puusanias, who tells us (ix. 16. 7) that there was no tomb of Alcmena at Thebes, because at her death she had been turned to stone. 182 THE LIBRARY, II. 1v.','J. G. Frazer',1921,'https://archive.org/details/library00athegoog','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0021','primary-verbatim',NULL,true,'Source is an OCR scan, located by name; verify wording and exact chapter.section against a clean edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
